//! `rpp`, `path_handler` and `shim` against the real nav2 `RotationShimController`
//! around `RegulatedPurePursuitController` (tests/data/rpp.json, regenerated by
//! tests/oracle/run_oracle.sh rpp).
//!
//! The oracle configured the plugins from `nav2_no_map_params.yaml` ("robot")
//! and from two variants that switch on the branches the yaml leaves off, and
//! drove them closed loop (unicycle at 20 Hz). Here every control cycle is
//! replayed open loop with the oracle's own inputs (pose, speed, costmap
//! window, plan / reset / speed-limit events), so float differences cannot
//! snowball.

mod common;

use common::{close, f, load};
use mower_nav_core::costmap::Costmap2D;
use mower_nav_core::footprint::robot_footprint;
use mower_nav_core::geometry::{yaw_from_quaternion, Pose2D, Transform2D, Twist2D};
use mower_nav_core::path_handler::calculate_path_length;
use mower_nav_core::rpp::{
    calculate_curvature, curvature_constraint, ControlInput, Controller, CostmapContext, RegulatedPurePursuit,
    RppParams,
};
use mower_nav_core::shim::{RotationShim, ShimParams};
use serde_json::Value;

fn pose(v: &Value) -> Pose2D {
    Pose2D::new(f(&v[0]), f(&v[1]), yaw_from_quaternion(0.0, 0.0, f(&v[2]), f(&v[3])))
}

fn plan(v: &Value) -> Vec<Pose2D> {
    v.as_array().unwrap().iter().map(pose).collect()
}

fn costmap(v: &Value) -> Costmap2D {
    let size_x = v["size_x"].as_u64().unwrap() as u32;
    let mut c = Costmap2D::new(
        size_x,
        v["size_y"].as_u64().unwrap() as u32,
        f(&v["resolution"]),
        f(&v["origin_x"]),
        f(&v["origin_y"]),
        0,
    );
    for cell in v["cells"].as_array().unwrap() {
        let i = cell[0].as_u64().unwrap() as u32;
        c.set_cost(i % size_x, i / size_x, cell[1].as_u64().unwrap() as u8);
    }
    c
}

/// The RPP parameters a node read (`FollowPath.*` as declared by nav2).
fn rpp_params(p: &Value) -> RppParams {
    let num = |k: &str| f(&p[format!("FollowPath.{k}")]);
    let flag = |k: &str| p[format!("FollowPath.{k}")].as_bool().unwrap_or_else(|| panic!("FollowPath.{k}"));
    RppParams {
        desired_linear_vel: num("desired_linear_vel"),
        lookahead_dist: num("lookahead_dist"),
        min_lookahead_dist: num("min_lookahead_dist"),
        max_lookahead_dist: num("max_lookahead_dist"),
        lookahead_time: num("lookahead_time"),
        rotate_to_heading_angular_vel: num("rotate_to_heading_angular_vel"),
        transform_tolerance: num("transform_tolerance"),
        use_velocity_scaled_lookahead_dist: flag("use_velocity_scaled_lookahead_dist"),
        min_approach_linear_velocity: num("min_approach_linear_velocity"),
        approach_velocity_scaling_dist: num("approach_velocity_scaling_dist"),
        max_allowed_time_to_collision_up_to_carrot: num("max_allowed_time_to_collision_up_to_carrot"),
        use_regulated_linear_velocity_scaling: flag("use_regulated_linear_velocity_scaling"),
        use_cost_regulated_linear_velocity_scaling: flag("use_cost_regulated_linear_velocity_scaling"),
        cost_scaling_dist: num("cost_scaling_dist"),
        cost_scaling_gain: num("cost_scaling_gain"),
        inflation_cost_scaling_factor: num("inflation_cost_scaling_factor"),
        regulated_linear_scaling_min_radius: num("regulated_linear_scaling_min_radius"),
        regulated_linear_scaling_min_speed: num("regulated_linear_scaling_min_speed"),
        use_fixed_curvature_lookahead: flag("use_fixed_curvature_lookahead"),
        curvature_lookahead_dist: num("curvature_lookahead_dist"),
        use_rotate_to_heading: flag("use_rotate_to_heading"),
        rotate_to_heading_min_angle: num("rotate_to_heading_min_angle"),
        max_angular_accel: num("max_angular_accel"),
        use_cancel_deceleration: flag("use_cancel_deceleration"),
        cancel_deceleration: num("cancel_deceleration"),
        allow_reversing: flag("allow_reversing"),
        max_robot_pose_search_dist: num("max_robot_pose_search_dist"),
        interpolate_curvature_after_goal: flag("interpolate_curvature_after_goal"),
        use_collision_detection: flag("use_collision_detection"),
        stateful: flag("stateful"),
        controller_frequency: f(&p["controller_frequency"]),
    }
}

/// The shim parameters a node read.
fn shim_params(p: &Value) -> ShimParams {
    let num = |k: &str| f(&p[format!("FollowPath.{k}")]);
    let flag = |k: &str| p[format!("FollowPath.{k}")].as_bool().unwrap_or_else(|| panic!("FollowPath.{k}"));
    ShimParams {
        angular_dist_threshold: num("angular_dist_threshold"),
        angular_disengage_threshold: num("angular_disengage_threshold"),
        forward_sampling_distance: num("forward_sampling_distance"),
        rotate_to_heading_angular_vel: num("rotate_to_heading_angular_vel"),
        max_angular_accel: num("max_angular_accel"),
        max_cost_threshold: num("max_cost_threshold"),
        simulate_ahead_time: num("simulate_ahead_time"),
        rotate_to_goal_heading: flag("rotate_to_goal_heading"),
        rotate_to_heading_once: flag("rotate_to_heading_once"),
        closed_loop: flag("closed_loop"),
        use_path_orientations: flag("use_path_orientations"),
        position_checker_stateful: p[".position_checker.stateful"].as_bool().unwrap(),
        controller_frequency: f(&p["controller_frequency"]),
    }
}

#[test]
fn params_match_the_yaml_as_nav2_reads_it() {
    let d = load("rpp.json");
    let robot = &d["configs"]["robot"];
    assert_eq!(rpp_params(&robot["params"]), RppParams::mower());
    assert_eq!(shim_params(&robot["params"]), ShimParams::mower());
    assert_eq!(f(&robot["xy_goal_tolerance"]), 0.05);
    // the shim's own position checker never sees the yaml (".position_checker.*")
    assert_eq!(f(&robot["params"][".position_checker.xy_goal_tolerance"]), 0.25);
    // min_distance_to_obstacle is in the yaml but no 1.3.13 plugin declares it
    assert!(robot["params"].get("FollowPath.min_distance_to_obstacle").is_none());
}

/// The yaml still says what `mower()` says (the oracle vectors were made
/// from it, so a change there needs both regenerated).
#[test]
fn mower_params_match_the_yaml() {
    let path = format!("{}/../../../mower_nav2/config/nav2_no_map_params.yaml", env!("CARGO_MANIFEST_DIR"));
    let text = std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("{path}: {e}"));
    let y: serde_yaml::Value = serde_yaml::from_str(&text).unwrap_or_else(|e| panic!("{path}: {e}"));
    let cs = &y["controller_server"]["ros__parameters"];
    let fp = &cs["FollowPath"];
    assert_eq!(fp["plugin"].as_str(), Some("nav2_rotation_shim_controller::RotationShimController"));
    assert_eq!(
        fp["primary_controller"].as_str(),
        Some("nav2_regulated_pure_pursuit_controller::RegulatedPurePursuitController")
    );
    let num = |k: &str| fp[k].as_f64().unwrap_or_else(|| panic!("FollowPath.{k}"));
    let flag = |k: &str| fp[k].as_bool().unwrap_or_else(|| panic!("FollowPath.{k}"));

    let s = ShimParams::mower();
    assert_eq!(cs["controller_frequency"].as_f64(), Some(s.controller_frequency));
    assert_eq!(num("angular_dist_threshold"), s.angular_dist_threshold);
    assert_eq!(num("forward_sampling_distance"), s.forward_sampling_distance);
    assert_eq!(num("angular_disengage_threshold"), s.angular_disengage_threshold);
    assert_eq!(num("rotate_to_heading_angular_vel"), s.rotate_to_heading_angular_vel);
    assert_eq!(num("max_angular_accel"), s.max_angular_accel);
    assert_eq!(num("simulate_ahead_time"), s.simulate_ahead_time);
    assert_eq!(flag("rotate_to_goal_heading"), s.rotate_to_goal_heading);

    let r = RppParams::mower();
    assert_eq!(cs["controller_frequency"].as_f64(), Some(r.controller_frequency));
    for (k, ours) in [
        ("desired_linear_vel", r.desired_linear_vel),
        ("lookahead_dist", r.lookahead_dist),
        ("min_lookahead_dist", r.min_lookahead_dist),
        ("max_lookahead_dist", r.max_lookahead_dist),
        ("lookahead_time", r.lookahead_time),
        ("transform_tolerance", r.transform_tolerance),
        ("min_approach_linear_velocity", r.min_approach_linear_velocity),
        ("approach_velocity_scaling_dist", r.approach_velocity_scaling_dist),
        ("max_allowed_time_to_collision_up_to_carrot", r.max_allowed_time_to_collision_up_to_carrot),
        ("curvature_lookahead_dist", r.curvature_lookahead_dist),
        ("cost_scaling_dist", r.cost_scaling_dist),
        ("cost_scaling_gain", r.cost_scaling_gain),
        ("regulated_linear_scaling_min_radius", r.regulated_linear_scaling_min_radius),
        ("regulated_linear_scaling_min_speed", r.regulated_linear_scaling_min_speed),
        ("rotate_to_heading_min_angle", r.rotate_to_heading_min_angle),
        ("max_robot_pose_search_dist", r.max_robot_pose_search_dist),
        // shared with the shim through the FollowPath namespace
        ("rotate_to_heading_angular_vel", r.rotate_to_heading_angular_vel),
        ("max_angular_accel", r.max_angular_accel),
    ] {
        assert_eq!(num(k), ours, "FollowPath.{k}");
    }
    for (k, ours) in [
        ("use_velocity_scaled_lookahead_dist", r.use_velocity_scaled_lookahead_dist),
        ("use_collision_detection", r.use_collision_detection),
        ("use_regulated_linear_velocity_scaling", r.use_regulated_linear_velocity_scaling),
        ("use_fixed_curvature_lookahead", r.use_fixed_curvature_lookahead),
        ("use_cost_regulated_linear_velocity_scaling", r.use_cost_regulated_linear_velocity_scaling),
        ("use_rotate_to_heading", r.use_rotate_to_heading),
        ("allow_reversing", r.allow_reversing),
        ("stateful", r.stateful),
    ] {
        assert_eq!(flag(k), ours, "FollowPath.{k}");
    }
    // the rest of the keys are upstream defaults, which mower() leaves alone
    let known = [
        "plugin",
        "primary_controller",
        "angular_dist_threshold",
        "forward_sampling_distance",
        "angular_disengage_threshold",
        "rotate_to_heading_angular_vel",
        "max_angular_accel",
        "simulate_ahead_time",
        "rotate_to_goal_heading",
        "desired_linear_vel",
        "lookahead_dist",
        "min_lookahead_dist",
        "max_lookahead_dist",
        "lookahead_time",
        "transform_tolerance",
        "use_velocity_scaled_lookahead_dist",
        "min_approach_linear_velocity",
        "approach_velocity_scaling_dist",
        "use_collision_detection",
        "max_allowed_time_to_collision_up_to_carrot",
        "use_regulated_linear_velocity_scaling",
        "use_fixed_curvature_lookahead",
        "curvature_lookahead_dist",
        "use_cost_regulated_linear_velocity_scaling",
        "cost_scaling_dist",
        "cost_scaling_gain",
        "regulated_linear_scaling_min_radius",
        "regulated_linear_scaling_min_speed",
        "use_rotate_to_heading",
        "allow_reversing",
        "rotate_to_heading_min_angle",
        "max_robot_pose_search_dist",
        "min_distance_to_obstacle", // not a 1.3.13 parameter
        "stateful",
    ];
    for (k, _) in fp.as_mapping().unwrap() {
        let k = k.as_str().unwrap();
        assert!(known.contains(&k), "FollowPath.{k} is new in the yaml: port it into RppParams / ShimParams::mower()");
    }
}

#[test]
fn costmap_context_matches_costmap_2d_ros() {
    let d = load("rpp.json");
    let c = &d["costmap"];
    let ctx = CostmapContext::local_costmap();
    let fp = c["footprint"].as_array().unwrap();
    assert_eq!(ctx.footprint.len(), fp.len());
    assert_eq!(ctx.footprint, robot_footprint(0.5));
    for (ours, theirs) in ctx.footprint.iter().zip(fp) {
        assert!(close(ours.0, f(&theirs[0])) && close(ours.1, f(&theirs[1])), "footprint {ours:?} vs {theirs}");
    }
    assert!(close(ctx.inscribed_radius, f(&c["inscribed"])));
    assert!(close(ctx.circumscribed_radius, f(&c["circumscribed"])));
    assert_eq!(ctx.tracking_unknown, c["tracking_unknown"].as_bool().unwrap());
    assert_eq!(c["global_frame"], "odom");
}

/// The one comparison where nav2 and this port part ways: the approach
/// slow-down starts when the transformed plan's integrated length drops
/// below `approach_velocity_scaling_dist`. mower_nav densifies every plan to
/// 0.1 m and the yaml sets 0.4, so for the ~8 cycles in which 5 poses are left
/// the length is 4 x 0.1 = 0.4 in exact arithmetic, and `<` is decided by the
/// last bit of tf2's transform (quaternion maths with FMA in nav2, sin / cos
/// here) and of glibc's vs this host's `hypot`.
///
/// When the last cycle sat on that edge (within 1e-12), returns the command
/// RPP gives on the *other* side of it. Only for configurations without cost
/// regulation, reversing and the fixed curvature lookahead (the robot's).
fn other_side_of_the_approach_edge(rpp: &RegulatedPurePursuit) -> Option<(f64, f64)> {
    let p = rpp.params();
    if p.use_cost_regulated_linear_velocity_scaling || p.allow_reversing || p.use_fixed_curvature_lookahead {
        return None;
    }
    let plan = rpp.transformed_plan();
    let remaining = calculate_path_length(plan);
    if (remaining - p.approach_velocity_scaling_dist).abs() > 1e-12 {
        return None;
    }
    let (cx, cy) = rpp.carrot()?;
    let curvature = calculate_curvature(cx, cy);
    let constrained = curvature_constraint(p.desired_linear_vel, curvature, p.regulated_linear_scaling_min_radius)
        .min(p.desired_linear_vel)
        .max(p.regulated_linear_scaling_min_speed);
    let scale = if remaining < p.approach_velocity_scaling_dist {
        1.0
    } else {
        let last = plan[plan.len() - 1];
        last.x.hypot(last.y) / p.approach_velocity_scaling_dist
    };
    let approach = (constrained * scale).max(p.min_approach_linear_velocity);
    let v = constrained.min(approach).abs().min(p.desired_linear_vel);
    Some((v, v * curvature))
}

#[derive(Default)]
struct Stats {
    cycles: usize,
    commands: usize,
    errors: usize,
    rotations: usize,
    approach_edges: usize,
    max_abs_diff: f64,
    max_at: String,
}

fn replay(config: &str) -> Stats {
    let d = load("rpp.json");
    let m = &d["map_from_odom"];
    let costmap_from_plan = Transform2D::new(f(&m[0]), f(&m[1]), f(&m[2])).inverse();
    let cfg = &d["configs"][config];
    let xy_goal_tolerance = f(&cfg["xy_goal_tolerance"]);
    let new_shim = || {
        if config == "robot" {
            RotationShim::mower()
        } else {
            let ctx = CostmapContext::local_costmap();
            let rpp = RegulatedPurePursuit::new(rpp_params(&cfg["params"]), ctx.clone());
            RotationShim::new(shim_params(&cfg["params"]), ctx, rpp)
        }
    };

    let mut failures: Vec<String> = Vec::new();
    let mut stats = Stats::default();
    let scenarios: Vec<&Value> = d["scenarios"].as_array().unwrap().iter().filter(|s| s["config"] == config).collect();
    assert!(!scenarios.is_empty(), "no {config} scenarios");
    for sc in scenarios {
        let name = sc["name"].as_str().unwrap();
        let mut shim = new_shim();
        let mut grid: Option<Costmap2D> = None;
        let mut cycle = 0usize;
        for step in sc["steps"].as_array().unwrap() {
            if let Some(p) = step.get("plan") {
                shim.set_plan(&plan(p));
            } else if step.get("reset").is_some() {
                shim.reset();
            } else if let Some(l) = step.get("speed_limit") {
                shim.set_speed_limit(f(&l[0]), l[1].as_bool().unwrap());
            } else if let Some(c) = step.get("costmap") {
                grid = Some(costmap(c));
            } else if let Some(c) = step.get("cycle") {
                let input = ControlInput {
                    pose: pose(&c["pose"]),
                    speed: Twist2D::new(f(&c["speed"][0]), 0.0, f(&c["speed"][1])),
                    xy_goal_tolerance,
                    costmap_from_plan,
                    costmap: grid.as_ref().expect("a costmap before the first cycle"),
                };
                let result = shim.compute_velocity_commands(&input);
                let at = format!("{name} cycle {cycle}");
                stats.cycles += 1;
                match (&result, c.get("out"), c.get("err")) {
                    (Ok(cmd), Some(out), None) => {
                        stats.commands += 1;
                        let theirs = (f(&out[0]), f(&out[1]), f(&out[2]));
                        if close(cmd.x, theirs.0) && close(cmd.y, theirs.1) && close(cmd.theta, theirs.2) {
                            for (a, b) in [(cmd.x, theirs.0), (cmd.y, theirs.1), (cmd.theta, theirs.2)] {
                                if (a - b).abs() > stats.max_abs_diff {
                                    stats.max_abs_diff = (a - b).abs();
                                    stats.max_at = format!("{at}: {cmd:?} vs {theirs:?}");
                                }
                            }
                        } else if other_side_of_the_approach_edge(shim.primary())
                            .is_some_and(|(v, w)| close(v, theirs.0) && theirs.1 == 0.0 && close(w, theirs.2))
                        {
                            stats.approach_edges += 1;
                        } else {
                            failures.push(format!("{at}: {cmd:?} vs {theirs:?}"));
                        }
                    }
                    (Err(e), None, Some(err)) => {
                        stats.errors += 1;
                        if e.class_name() != err[0] || e.what() != err[1] {
                            failures.push(format!("{at}: {e} vs {err}"));
                        }
                    }
                    (ours, out, err) => failures.push(format!("{at}: {ours:?} vs out {out:?} err {err:?}")),
                }
                if shim.in_rotation() {
                    stats.rotations += 1;
                }
                let theirs = (c["rot"].as_bool().unwrap(), c["upd"].as_bool().unwrap(), c["plan"].as_u64().unwrap());
                let ours = (shim.in_rotation(), shim.path_updated(), shim.primary().plan().len() as u64);
                if ours != theirs {
                    failures.push(format!("{at}: (in_rotation, path_updated, plan size) {ours:?} vs {theirs:?}"));
                }
                cycle += 1;
            }
        }
    }
    eprintln!(
        "{config}: {} cycles: {} commands ({} in-place rotations by the shim), {} exceptions; largest float \
         difference {:e} ({}); {} cycles on the approach edge (nav2 took the other side, matched to TOL)",
        stats.cycles,
        stats.commands,
        stats.rotations,
        stats.errors,
        stats.max_abs_diff,
        stats.max_at,
        stats.approach_edges
    );
    assert!(
        failures.is_empty(),
        "{config}: {} mismatches, first ones:\n{}",
        failures.len(),
        failures.iter().take(25).cloned().collect::<Vec<_>>().join("\n")
    );
    stats
}

/// nav2_no_map_params.yaml: every scenario the robot's configuration reaches.
#[test]
fn robot_follow_path_replay() {
    let s = replay("robot");
    assert!(s.rotations > 0 && s.errors > 0);
}

/// RPP rotate-to-heading (goal and path), velocity-scaled lookahead, the
/// negative max_robot_pose_search_dist; the shim open loop with
/// rotate_to_heading_once.
#[test]
fn variant_a_replay() {
    replay("variant_a");
}

/// RPP reversing through a cusp, the fixed curvature lookahead interpolated
/// past the goal, cost regulation; the shim's rotate_to_goal_heading and
/// use_path_orientations.
#[test]
fn variant_b_replay() {
    replay("variant_b");
}
